const b = $json.body || $json;
const url = String(b.url || '').trim();
const cliente = String(b.cliente || b.slug || '').trim() || 'sin-slug';
const contacto = String(b.whatsapp || b.telefono || b.email || '').trim();
const modo = String(b.modo || 'piloto').trim(); // piloto | cobrado
if (!/^https?:\/\//i.test(url)) {
  return [{ json: { ok: false, error: 'url inválida', sistema: '06-auditorias-locales' } }];
}
const jobId = `AUD-${Date.now()}`;
return [{ json: {
  ok: true,
  sistema: '06-auditorias-locales',
  etapa: 'audit_entrada',
  jobId,
  url,
  cliente,
  contacto,
  modo,
  status: 'queued',
  entregable_esperado: ['MARKETING-AUDIT.md', 'MARKETING-AUDIT.html'],
  siguiente: 'enviar_informe_luego_ofrecer_plan',
  todo: 'TODO_CREDENCIAL: HTTP → marketing_audit_main.py audit --url … --slug …',
  at: new Date().toISOString()
}}];
